import React from "react";
import "./VideoGrid.css";

function VideoGrid() {
  // Example array of video data
  const videos = Array.from({ length: 12 }, (_, index) => ({
    id: index + 1,
    title: `Amazing Video Title ${index + 1}`,
    channel: `Channel Name ${index + 1}`,
    views: `${(index + 1) * 1000} views`,
    time: `${index + 1} days ago`,
    thumbnail: "https://avatars.mds.yandex.net/i?id=ea2552b2dbee1b25c0dc20cab80b4604e5684af9-5690699-images-thumbs&n=13",
  }));

  return (
    <div className="main">
      <div className="video-grid-container">
        {videos.map((video) => (
          <div key={video.id} className="youtube-card">
            <div className="youtube-card-thumbnail">
              <img
                src={video.thumbnail}
                alt={`Thumbnail for ${video.title}`}
                className="thumbnail-image"
              />
            </div>
            <div className="youtube-card-content">
              <h3 className="video-title">{video.title}</h3>
              <p className="channel-name">{video.channel}</p>
              <div className="video-stats">
                <span className="views">{video.views}</span>
                <span className="time">{video.time}</span>
              </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

export default VideoGrid;
